using System;using System.IO;using System.Diagnostics;using System.Collections.Concurrent;using System.Threading;using System.Threading.Tasks;using SpatialWallpaper.Sdk.Capabilities;
namespace SpatialWallpaper.Supervision.Broker {
 // Authenticated manager-only channel. A bounded mailbox separates native
 // callbacks from Host I/O. The Host remains the authority for focus and epoch.
 public sealed class DesktopInputChannel:IDesktopInputTarget,IDisposable {
  const uint Magic=0x31444953;const int Size=56,IoMs=200;
  readonly Stream stream;readonly object sync=new object();readonly BlockingCollection<Pending> queue=new BlockingCollection<Pending>(64);
  readonly TaskCompletionSource<bool> completion=new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);
  InputFocusConfirmation confirmation;bool closed;long invalidation,acknowledgedInvalidation;
  sealed class Pending{internal byte[] Bytes;internal long Generation;}
  public Task Completion=>completion.Task;public string Failure{get;private set;}
  public DesktopInputChannel(Stream authenticatedStream){stream=authenticatedStream??throw new ArgumentNullException(nameof(authenticatedStream));try{confirmation=ReadConfirmation(stream);if(confirmation.Focused)throw new InvalidDataException("desktop-source-initial-focus");}catch{stream.Dispose();queue.Dispose();throw;}Task.Run(Run);}
  public ulong CaptureEpoch{get{lock(sync){if(closed)throw new ObjectDisposedException(nameof(DesktopInputChannel));return confirmation.Epoch;}}}
  public InputFocusConfirmation GetFocusConfirmation(){lock(sync){bool ready=!closed&&acknowledgedInvalidation==invalidation;return new InputFocusConfirmation(confirmation.Epoch,ready&&confirmation.Focused,ready);}}
  static void ObserveFault(Task task){task.ContinueWith(done=>{var observed=done.Exception;},CancellationToken.None,TaskContinuationOptions.OnlyOnFaulted|TaskContinuationOptions.ExecuteSynchronously,TaskScheduler.Default);}
  static long Deadline()=>Stopwatch.GetTimestamp()+IoMs*Stopwatch.Frequency/1000;
  static int Remaining(long deadline){long left=(deadline-Stopwatch.GetTimestamp())*1000/Stopwatch.Frequency;if(left<=0)throw new TimeoutException("desktop-input-io-deadline");return (int)left;}
  static void Read(Stream stream,byte[] bytes){long deadline=Deadline();int at=0;while(at<bytes.Length){var pending=stream.ReadAsync(bytes,at,bytes.Length-at);ObserveFault(pending);if(!pending.Wait(Remaining(deadline)))throw new TimeoutException("desktop-input-read");int count=pending.GetAwaiter().GetResult();if(count==0)throw new EndOfStreamException();at+=count;}}
  static void Write(Stream stream,byte[] bytes){var pending=stream.WriteAsync(bytes,0,bytes.Length);ObserveFault(pending);if(!pending.Wait(IoMs))throw new TimeoutException("desktop-input-write");pending.GetAwaiter().GetResult();}
  static InputFocusConfirmation ReadConfirmation(Stream stream){var bytes=new byte[24];Read(stream,bytes);ulong epoch=BitConverter.ToUInt64(bytes,8);uint flags=BitConverter.ToUInt32(bytes,16);if(BitConverter.ToUInt32(bytes,0)!=Magic||BitConverter.ToUInt32(bytes,4)!=1||epoch==0||flags>1||BitConverter.ToUInt32(bytes,20)!=0)throw new InvalidDataException("desktop-input-confirmation");return new InputFocusConfirmation(epoch,flags==1);}
  static void Confirm(Stream stream,InputTarget target){var state=target.GetFocusConfirmation();var bytes=new byte[24];using(var writer=new BinaryWriter(new MemoryStream(bytes))){writer.Write(Magic);writer.Write(1u);writer.Write(state.Epoch);writer.Write(state.Focused?1u:0u);writer.Write(0u);}Write(stream,bytes);}
  static byte[] Empty(uint operation){var bytes=new byte[Size];bytes[0]=1;bytes[4]=(byte)operation;return bytes;}
  static byte[] Encode(uint operation,InputObservation value){var bytes=new byte[Size];using(var writer=new BinaryWriter(new MemoryStream(bytes))){writer.Write(1u);writer.Write(operation);writer.Write(value.Sequence);writer.Write(value.Time);writer.Write(value.CaptureEpoch);writer.Write((value.Target?1u:0)|(value.Foreground?2u:0)|(value.ShellFocus?4u:0)|(value.Session?8u:0)|(value.Adapter?16u:0)|(value.Modifier?32u:0)|(value.PrimaryDown?64u:0)|(value.Heartbeat?128u:0));writer.Write(value.Held);writer.Write(value.X);writer.Write(value.Y);writer.Write(value.Wheel);writer.Write(0u);}return bytes;}
  void Enqueue(byte[] packet,bool revoke){bool full;lock(sync){if(closed){if(revoke)return;throw new ObjectDisposedException(nameof(DesktopInputChannel));}if(revoke){++invalidation;confirmation=new InputFocusConfirmation(confirmation.Epoch,false);while(queue.TryTake(out var ignored)){} }full=!queue.TryAdd(new Pending{Bytes=packet,Generation=invalidation});}if(full){Dispose();throw new IOException("desktop-input-mailbox-full");}}
  public void Observe(InputObservation value)=>Enqueue(Encode(1,value),false);
  public void AcquireFocus(InputObservation value)=>Enqueue(Encode(3,value),false);
  public void Revoke()=>Enqueue(Empty(2),true);
  void Run(){try{while(true){Pending work;if(!queue.TryTake(out work,80)){lock(sync){if(closed)break;work=new Pending{Bytes=Empty(4),Generation=invalidation};}}lock(sync){if(closed)break;if(work.Generation!=invalidation)continue;}Write(stream,work.Bytes);var received=ReadConfirmation(stream);lock(sync){if(received.Epoch<confirmation.Epoch)throw new InvalidDataException("desktop-input-epoch-regressed");if(work.Bytes[4]==2&&work.Generation==invalidation)acknowledgedInvalidation=work.Generation;confirmation=new InputFocusConfirmation(received.Epoch,!closed&&work.Generation==invalidation&&received.Focused);}}}catch(Exception error){Failure=error is TimeoutException?"deadline":error is InvalidDataException?"protocol":error.GetType().Name;}finally{lock(sync){closed=true;confirmation=new InputFocusConfirmation(confirmation.Epoch,false);queue.CompleteAdding();}try{stream.Dispose();queue.Dispose();completion.TrySetResult(true);}catch(Exception error){completion.TrySetException(error);}}}
  public static void Serve(Stream stream,InputTarget target){if(stream==null||target==null)throw new ArgumentNullException();target.Owner.AttachSource(target,false);try{Confirm(stream,target);long sequence=0;while(!target.Closed){var bytes=new byte[Size];Read(stream,bytes);using(var reader=new BinaryReader(new MemoryStream(bytes))){if(reader.ReadUInt32()!=1)throw new InvalidDataException("desktop-input-version");uint operation=reader.ReadUInt32();if(operation==2||operation==4){for(int i=8;i<Size;i++)if(bytes[i]!=0)throw new InvalidDataException("desktop-input-empty-shape");if(operation==2)target.Revoke();}else if(operation==1||operation==3){long next=reader.ReadInt64(),time=reader.ReadInt64();ulong epoch=reader.ReadUInt64();uint flags=reader.ReadUInt32(),held=reader.ReadUInt32();float x=reader.ReadSingle(),y=reader.ReadSingle();int wheel=reader.ReadInt32();if(next<=sequence||next<=0||(flags&~255u)!=0||reader.ReadUInt32()!=0)throw new InvalidDataException("desktop-input-fields");sequence=next;var value=new InputObservation(next,time,(flags&1)!=0,(flags&2)!=0,(flags&4)!=0,(flags&8)!=0,(flags&16)!=0,(flags&32)!=0,(flags&64)!=0,held,x,y,wheel,epoch,(flags&128)!=0);if(operation==3)target.AcquireFocus(value);else target.Observe(value);}else throw new InvalidDataException("desktop-input-operation");}Confirm(stream,target);}}finally{target.Owner.DetachSource(target);}}
  public void Dispose(){lock(sync){if(closed)return;closed=true;++invalidation;confirmation=new InputFocusConfirmation(confirmation.Epoch,false);queue.CompleteAdding();}Task.Run(()=>{try{stream.Dispose();}catch{}});}
 }
}
